using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Quotations.Commands.ApproveQuotation;public sealed class ApproveQuotationCommandHandler(IQuotationRepository repository,IUserRepository users,IApplicationDbContext db):IRequestHandler<ApproveQuotationCommand,Result<QuotationDto>>{public async Task<Result<QuotationDto>>Handle(ApproveQuotationCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<QuotationDto>(QuotationErrors.NotFound);if(e.Status.ToString()!="Sent")return Result.Failure<QuotationDto>(QuotationErrors.NotDraft);if(!await users.ExistsByIdAsync(request.ApprovedByUserId,cancellationToken))return Result.Failure<QuotationDto>(new Error("Quotations.UserNotFound","The user was not found.",ErrorType.NotFound));e.Approve(request.ApprovedByUserId,request.ApprovedAt);await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationDto.FromEntity(e));}}
